  // We're trying to reserve the high byte of the flags for view flags, so,
  // don't add flags to the high byte if possible.

  /// The flags we don't want written to X-Mozilla-Status/X-Mozilla-Status2.
  const nsMsgMessageFlagType RuntimeOnly     = Elided | New | Offline;
};

// Ask compactListener if we should keep this message.
bool keepMsg;
nsresult rv = mCompactListener->OnRetentionQuery(storeToken, &mMsgFlags,
                                                 mMsgKeywords, &keepMsg);
if (NS_FAILED(rv)) {
  return rv;  // Abort the scan.
}

// Some flags are really folder state, not message state.
// We don't want to write them into the message.
mMsgFlags &= ~nsMsgMessageFlags::RuntimeOnly;

// static
nsresult nsMsgLocalStoreUtils::PatchXMozillaStatusHeaders(
    nsIRandomAccessStream* stream, int64_t msgStart,
    StatusDetails const& details, uint32_t newFlags) {
  nsresult rv;

  // Some flags are really folder state, not message state.
  // So we don't want to store them in X-Mozilla-Status headers.
  newFlags &= ~nsMsgMessageFlags::RuntimeOnly;

  // Preserve the Queued flag from existing X-Mozilla-Status header.
  // (Note: kept for historical reasons, probably worth revisiting).
  newFlags |= (details.msgFlags & nsMsgMessageFlags::Queued);

if (mozstatus) {
  if (mozstatus->length == 4) {
    NS_ASSERTION(MsgIsHex(mozstatus->value, 4),
                 "Expected 4 hex digits for X-Mozilla-Status.");
    flags = MsgUnhex(mozstatus->value, 4);
    // strip off and remember priority bits.
    flags &= ~nsMsgMessageFlags::RuntimeOnly;
    priorityFlags =
        (nsMsgPriorityValue)((flags & nsMsgMessageFlags::Priorities) >> 13);
    flags &= ~nsMsgMessageFlags::Priorities;
  }
}

if (mozstatus2) {
  if (mozstatus2->length == 8) {
    NS_ASSERTION(MsgIsHex(mozstatus2->value, 8),
                 "Expected 8 hex digits for X-Mozilla-Status2.");
    uint32_t flags2 = MsgUnhex(mozstatus2->value, 8);
    flags2 &= ~nsMsgMessageFlags::RuntimeOnly;
    flags |= flags2 & 0xFFFF0000;

// These are the default X-Mozilla- headers for local folders (they are
// re-written in place when flags and keywords are modified).
const xhdrs =
  `X-Mozilla-Status: 0000\r\n` +
  `X-Mozilla-Status2: 00000000\r\n` +
  `X-Mozilla-Keys:                                                                                 \r\n`;

const bigxhdrs =
  `X-Mozilla-Status: 0000\r\n` +
  `X-Mozilla-Status2: 00000000\r\n` +
  `X-Mozilla-Keys: ${bigKeyword}\r\n`;

// The messages we expect to see in the final mbox:
const outMsgs = [
  `${bigxhdrs}${hdrs1}\r\n${bod1}`,
  `${xhdrs}${hdrs3}\r\n${bod3}`,
];

loadMsgs(inbox, inMsgs);

